import datetime,re
from cryptography import x509
from cryptography.hazmat.primitives import hashes

def assess(pem, expected_uri, now, min_remaining):
    if not isinstance(pem,bytes) or len(pem)>65536 or not re.fullmatch(rb'\s*-----BEGIN CERTIFICATE-----\r?\n[A-Za-z0-9+/=\r\n]+-----END CERTIFICATE-----\s*',pem):
        raise ValueError('exactly one bounded PEM certificate required')
    if not isinstance(expected_uri,str) or not re.fullmatch(r'spiffe://[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?/ns/[a-z0-9](?:[a-z0-9-]*[a-z0-9])?/sa/[a-z0-9](?:[a-z0-9-]*[a-z0-9])?',expected_uri):
        raise ValueError('expected Istio workload URI')
    if type(now) is not int or type(min_remaining) is not int or not 0<=now<=253402300799 or min_remaining<0:
        raise ValueError('integer UTC seconds required')
    try:
        cert=x509.load_pem_x509_certificate(pem)
        utc=datetime.timezone.utc
        before=int(cert.not_valid_before.replace(tzinfo=utc).timestamp())
        after=int(cert.not_valid_after.replace(tzinfo=utc).timestamp())
        try:uris=cert.extensions.get_extension_for_class(x509.SubjectAlternativeName).value.get_values_for_type(x509.UniformResourceIdentifier)
        except x509.ExtensionNotFound:uris=[]
    except Exception as error:
        raise ValueError('invalid X.509 encoding or extensions') from error
    reasons=[]
    if now<before:reasons.append('not_yet_valid')
    if now>=after:reasons.append('expired')
    if now<after and after-now<min_remaining:reasons.append('rotation_budget')
    if uris!=[expected_uri]:reasons.append('workload_identity')
    return {'metadata_ready':not reasons,'reasons':reasons,'uri_sans':uris,'not_before':before,'not_after':after,'remaining_seconds':after-now,
            'sha256':cert.fingerprint(hashes.SHA256()).hex(),'trust_verified':False,'live_mtls':'not_tested'}
